const isBlocked=u=>!!u&&myBlocks().some(b=>b.id===u.id||(u.cloudId&&b.cloudId===u.cloudId));
const remoteBlocked=id=>myBlocks().some(b=>b.cloudId===id||b.id===id);
const saveBlocks=l=>{S.st.blocks={...(S.st.blocks||{}),[S.me.id]:l};return put('kv',S.st)};
const authH=()=>S.me?.apiToken?{authorization:'Bearer '+S.me.apiToken}:{};
async function syncBlocks(){try{if(!S.me?.apiToken)return;const d=await api('/api/blocks'),l=myBlocks().slice();let ch=false;for(const b of d.blocks||[])if(!l.some(x=>x.cloudId===b.id||x.id===b.id)){l.push({id:b.id,cloudId:b.id,name:b.name});ch=true}if(ch)await saveBlocks(l)}catch{}}
const urls=new WeakMap();
const src=b=>{if(!b)return'';if(!urls.has(b))urls.set(b,URL.createObjectURL(b));return urls.get(b)};

/* tema, fonte */
function theme(){const d=document.documentElement,t=S.st.theme==='auto'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):S.st.theme;d.dataset.theme=t;d.dataset.font=S.st.font||'padrao';d.dataset.motion=S.st.motion||'auto';d.style.fontSize=S.st.size+'%';document.querySelector('meta[name=theme-color]').content=t==='dark'?'#050505':'#ffffff'}
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',theme);

/* utilitários */
let tt;const toast=m=>{const t=$('toast');t.textContent=m;t.classList.add('on');clearTimeout(tt);tt=setTimeout(()=>t.classList.remove('on'),2400)};
const sheet=h=>{$('sh').style.transform='';$('sh').style.transition='';$('sh').innerHTML=h;$('ov').classList.add('on');$('sh').classList.add('on')};
const closeSheet=()=>{$('sh').style.transform='';$('sh').style.transition='';$('ov').classList.remove('on');$('sh').classList.remove('on')};
async function hash(p,salt){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+p));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function shrink(f,max=S.st.saver==='on'?800:1280){const bm=await createImageBitmap(f),k=Math.min(1,max/Math.max(bm.width,bm.height)),c=document.createElement('canvas');c.width=Math.round(bm.width*k);c.height=Math.round(bm.height*k);c.getContext('2d').drawImage(bm,0,0,c.width,c.height);return new Promise(r=>c.toBlob(r,'image/jpeg',.82))}
const av=(u,s)=>`<div class="av" style="width:${s}px;height:${s}px;font-size:${s*.38}px">${u.foto?`<img src="${src(u.foto)}" alt="">`:esc((u.nome||'?').slice(0,2).toUpperCase())}</div>`;
async function notify(uid,txt,kind='candidaturas'){const n={id:nid(),uid,txt,at:Date.now(),read:false};S.notifs.push(n);put('notifs',n);if(S.me&&uid===S.me.id){if(S.st.notif?.[kind]!==false&&document.hidden&&'Notification'in window&&Notification.permission==='granted'){const r=await navigator.serviceWorker.ready;r.showNotification('Aquipay',{body:T(txt),icon:'icon-192.png',badge:'icon-192.png'})}if(S.v==='home')render()}}
const unread=()=>S.notifs.filter(n=>n.uid===S.me.id&&!n.read).length;
const unreadMessages=()=>S.messages.filter(m=>m.to===S.me.id&&!m.read).length;

/* reputação */
function stats(id){const r=S.reviews.filter(x=>x.ownerId===id&&x.type!=='rating'),p=r.filter(x=>x.paid).length,ratings=S.reviews.filter(x=>x.type==='rating'&&x.targetId===id);return{n:r.length,p,pct:r.length?Math.round(p/r.length*100):null,list:r.slice(-5).reverse(),ratingCount:ratings.length,ratingAvg:ratings.length?ratings.reduce((a,x)=>a+x.stars,0)/ratings.length:0,ratingList:ratings.slice(-5).reverse()}}
const trust=(u,s)=>u.verified&&s.n>=3&&s.pct>=80?'Pagador de confiança':s.n?(s.pct>=80?'Bom histórico de pagamentos':'Histórico de pagamentos irregular'):'Ainda sem histórico de pagamentos';
function profile(u){const s=stats(u.id),own=S.me&&S.me.id===u.id,canRate=S.me&&!own&&S.cands.some(c=>c.status==='pago'&&((c.userId===S.me.id&&c.ownerId===u.id)||(c.ownerId===S.me.id&&c.userId===u.id))),already=S.reviews.some(x=>x.type==='rating'&&x.targetId===u.id&&x.reviewerId===S.me?.id);const stars=starsHtml;return`<div class="pf">${av(u,72)}<h2>${esc(u.nome)} ${u.verified?ic('badge','ok'):''}</h2><p class="mut">${trust(u,s)}</p>${u.cidade?`<p class="mut">${ic('pin','s')} ${esc(u.cidade)}</p>`:''}</div><div class="gr"><div><b>${u.verified?'Sim':'Não'}</b><small>Verificado</small></div><div><b>${s.n}</b><small>Interações concluídas</small></div><div><b>${s.ratingCount?`<span class="inl">${s.ratingAvg.toFixed(1)} ${ic('star','fill star s')}</span>`:'—'}</b><small>${s.ratingCount===1?'avaliação':'avaliações'}</small></div></div>${u.bio?`<p>${esc(u.bio)}</p>`:''}${u.professions?.length?`<h4>Profissões</h4><p>${u.professions.map(esc).join(' · ')}</p>`:''}${u.skills?.length?`<h4>Competências</h4><p>${u.skills.map(esc).join(' · ')}</p>`:''}${u.experience?.length?`<h4>Experiência profissional</h4>${u.experience.map(x=>`<div class="row2"><span>${esc(x.role||x.title||x)}</span><small>${esc(x.company||x.period||'')}</small></div>`).join('')}`:''}${u.education?.length?`<h4>Formação</h4>${u.education.map(x=>`<div class="row2"><span>${esc(x.course||x.title||x)}</span><small>${esc(x.school||x.year||'')}</small></div>`).join('')}`:''}${u.portfolio?.length?`<h4>Portefólio</h4>${u.portfolio.map(x=>`<div class="card"><b>${esc(x.title||x.name||'Trabalho')}</b><p class="mut">${esc(x.description||'')}</p></div>`).join('')}`:''}<h4>Classificações</h4><p class="pr">${s.ratingCount?stars(Math.round(s.ratingAvg))+' '+s.ratingAvg.toFixed(1)+' de 5':'Ainda sem classificações'}</p>${s.ratingList.map(x=>`<div class="card"><b>${stars(x.stars)}</b><p>${esc(x.comment||'Sem comentário')}</p></div>`).join('')}${canRate&&u.cloudId&&S.me?.apiToken?`<button class="btn" data-a="rateRemote" data-id="${u.cloudId}">Classificar com estrelas</button>`:canRate&&!already?`<button class="btn" data-a="rate" data-id="${u.id}">Classificar este perfil</button>`:already?'<p class="mut">Já classificaste este perfil.</p>':!own?'<p class="mut">A classificação fica disponível depois de uma interação concluída entre vocês.</p>':''}<h4>Histórico</h4>${s.list.length?s.list.map(x=>`<div class="row2"><span>${esc(x.title)}</span><span class="${x.paid?'ok':'bad'}">${x.paid?'Pago':'Não pago'}</span></div>`).join(''):'<p class="mut">Ainda não há trabalhos concluídos com este utilizador.</p>'}<p class="mut" style="margin-top:1rem">Membro desde ${fmtMonth(u.at)}</p>${S.me&&!own?`<div class="share-actions"><button class="btn secondary" data-a="report" data-t="user" data-id="${u.id}" data-cid="${u.cloudId||''}">Denunciar perfil</button><button class="btn secondary" data-a="blockUser" data-id="${u.id}" data-cid="${u.cloudId||''}">Bloquear</button></div>`:''}`}

