const GLOGO='<svg viewBox="0 0 48 48" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg>';
const googleBtn=`<p class="or">ou</p><div class="gbtn" id="gbtn"><button class="btn secondary" data-a="googleSetup">${GLOGO}Continuar com Google</button></div>`;
const auth=reg=>`<div class="auth"><h1 class="logo">${LOGO}</h1>${reg?'<h2 class="auth-title">Cria a tua conta</h2>':''}<p class="err" id="err" role="alert"></p>${reg?fd('Nome','rn','text','','autocomplete="name"')+fd('Email','re','email','','autocomplete="email"')+fd('Palavra-passe','rp','password','Mínimo 10 caracteres','autocomplete="new-password"')+'<button class="btn" data-a="register">Criar conta</button>'+googleBtn+'<p class="sw">Já tens conta? <a class="link" data-a="toLogin">Entrar</a></p>':fd('Email','le','email','','autocomplete="username"')+fd('Palavra-passe','lp','password','','autocomplete="current-password"')+'<p class="sw" style="margin-top:-.2rem"><a class="link" data-a="forgot">Esqueceste-te da palavra-passe?</a></p><button class="btn" data-a="login">Entrar</button>'+googleBtn+'<p class="sw">Ainda não tens conta? <a class="link" data-a="toReg">Criar conta</a></p>'}<p class="sw"><a class="link" data-a="explore">Explorar perfis públicos</a></p><p class="legal-note">${T('Ao continuar, aceitas os {a} e a {b}.',{a:'<a class="link" data-a="openDoc" data-id="termos">'+T('Termos de Uso')+'</a>',b:'<a class="link" data-a="openDoc" data-id="privacidade">'+T('Política de Privacidade')+'</a>'})}</p></div>`;
async function loadGoogle(){if(window.google?.accounts?.id)return true;return new Promise(ok=>{const t=document.createElement('script');t.src='https://accounts.google.com/gsi/client';t.async=true;t.onload=()=>ok(true);t.onerror=()=>ok(false);document.head.appendChild(t)})}
async function initGoogle(){const box=$('gbtn');if(!box||!CFG.googleClientId)return;if(!(await loadGoogle())||!window.google?.accounts?.id)return;const b=$('gbtn');if(!b)return;google.accounts.id.initialize({client_id:CFG.googleClientId,callback:googleDone,ux_mode:'popup',auto_select:false,cancel_on_tap_outside:true});b.innerHTML='';google.accounts.id.renderButton(b,{type:'standard',theme:document.documentElement.dataset.theme==='dark'?'filled_black':'outline',size:'large',shape:'pill',text:'continue_with',logo_alignment:'left',locale:GOOGLE_LOCALES[LANG],width:Math.min(Math.round(b.clientWidth)||320,400)})}
async function googleDone(resp){const fail=m=>{const r=$('err');r?r.textContent=m:toast(m)};try{if(S.securityReauth){S.securityReauth=false;return await A.beginTotpSetup({googleCredential:resp.credential})}const res=await fetch(CFG.apiBase+'/api/auth/google',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({credential:resp.credential})});const cloud=await res.json().catch(()=>({}));if(!res.ok)return fail(cloud.error||'Não foi possível entrar com Google.');if(cloud.requiresTwoFactor&&cloud.challengeId){S.authChallenge=cloud.challengeId;S.authGoogle=true;render();return}if(!cloud.token||!cloud.user)return fail('Resposta de autenticação inválida.');await completeCloudLogin(cloud,true)}catch{fail('Não foi possível ligar ao servidor. Tenta novamente.')}}
const bar=t=>`<header class="top"><button class="btn ic" data-a="back" aria-label="Fechar">${ic('x')}</button><h2>${t}</h2><span style="width:2.5rem"></span></header>`;
const searchBox=(id,ph,val,clr)=>`<div class="sf">${ic('search')}<input id="${id}" type="search" placeholder="${ph}" value="${esc(val||'')}" aria-label="${ph}" autocomplete="off" enterkeyhint="search"><button type="button" class="search-clear" data-a="${clr}" aria-label="Limpar pesquisa">${ic('x')}</button></div>`;
const empty=(a,b)=>`<div class="empty"><b>${a}</b>${b}</div>`;
const pics=f=>f&&f.length?`<div class="ph">${f.map(b=>`<img src="${src(b)}" alt="Foto do anúncio" loading="lazy">`).join('')}</div>`:'';
function card(v){const o=U(v.ownerId)||{nome:'Utilizador'},mine=S.me.id===v.ownerId,done=S.cands.some(c=>c.vagaId===v.id&&c.userId===S.me.id);return`<article class="card">${pics(v.fotos)}<div class="ho">${av(o,40)}<div style="flex:1"><b>${esc(o.nome)}</b> ${o.verified?ic('badge','ok s'):''}<small>${ago(v.at)}</small></div><button class="btn secondary" style="width:auto" data-a="viewProfile" data-id="${o.id}">Perfil</button></div><h3>${esc(v.titulo)}</h3><p class="mut">${ic('pin','s')} ${esc(v.local||T('Local a combinar'))} · ${T(TIPO[v.tipo])}</p><p class="pr">${v.preco?kz(v.preco):'A combinar'}</p>${v.desc?`<p class="ds">${esc(v.desc)}</p>`:''}<div class="share-actions"><button class="btn secondary" data-a="sharePost" data-id="${v.id}">Partilhar</button><button class="btn secondary" data-a="copyPost" data-id="${v.id}">Copiar link</button></div>${mine?'<div class="mine-actions"><span class="pill">O teu anúncio</span><button class="btn secondary danger-outline" data-a="askDeleteListing" data-id="${v.id}">Eliminar</button></div>':`<button class="btn" data-a="apply" data-id="${v.id}" ${done?'disabled':''}>${done?'Candidatura enviada':'Candidatar-me'}</button>`}${mine?'':`<p class="rep"><a class="link" data-a="report" data-t="listing" data-id="${v.id}">Denunciar anúncio</a> · <a class="link" data-a="blockUser" data-id="${o.id}">Bloquear utilizador</a></p>`}</article>`}
const ST={enviada:'Enviada',aceite:'Aceite',concluida:'Concluída',pago:'Pagamento confirmado',nao_pago:'Pagamento não recebido'};
function candCard(c){const v=S.vagas.find(x=>x.id===c.vagaId)||{titulo:'Anúncio removido'};return`<div class="card"><h3>${esc(v.titulo)}</h3><p class="mut">${ago(c.at)} · ${c.spent?T('-{n} moedas',{n:c.spent}):T('sem custo')}</p><p style="margin:.5rem 0"><span class="pill">${ST[c.status]}</span></p>${c.status==='concluida'?`<div class="stack"><button class="btn" data-a="paid" data-id="${c.id}" data-v="1">Recebi o pagamento</button><button class="btn" data-a="paid" data-id="${c.id}" data-v="0">Não recebi</button></div>`:''}</div>`}
function mineCard(v){const n=S.cands.filter(c=>c.vagaId===v.id).length;return`<div class="card"><h3>${esc(v.titulo)}</h3><p class="mut">${n} candidatura${n===1?'':'s'}</p><div class="mine-actions"><button class="btn" data-a="cands" data-id="${v.id}">Ver candidatos</button><button class="btn secondary danger-outline" data-a="askDeleteListing" data-id="${v.id}">Eliminar anúncio</button></div></div>`}
function feed(){if(S.tab==='vagas'){const q=norm(S.searchText);const l=S.vagas.filter(v=>v.status==='ativa'&&!isBlocked(U(v.ownerId))&&(!q||norm([v.titulo,v.desc,v.local,T(TIPO[v.tipo]),U(v.ownerId)?.nome].join(' ')).includes(q))).sort((a,b)=>b.at-a.at);const people=q?S.users.filter(u=>u.id!==S.me.id&&!isBlocked(u)&&norm([u.nome,u.cidade,u.bio,(u.professions||[]).join(' ')].join(' ')).includes(q)):[];const peopleHtml=people.length?`<h4>Perfis encontrados</h4>${people.slice(0,12).map(u=>`<div class="card ho">${av(u,42)}<div style="flex:1"><b>${esc(u.nome)}</b><small>${esc(u.cidade||'')} · ${(u.professions||[]).map(esc).join(', ')}</small></div><button class="btn secondary" style="width:auto" data-a="viewProfile" data-id="${u.id}">Ver perfil</button></div>`).join('')}`:'';return (l.length?l.map(card).join(''):empty('Ainda não há anúncios','Publica o primeiro trabalho ou emprego da tua zona.'))+peopleHtml}
if(S.tab==='cand'){const l=S.cands.filter(c=>c.userId===S.me.id).sort((a,b)=>b.at-a.at);return l.length?l.map(candCard).join(''):empty('Sem candidaturas','As vagas a que te candidatares aparecem aqui.')}
const l=S.vagas.filter(v=>v.ownerId===S.me.id).sort((a,b)=>b.at-a.at);return l.length?l.map(mineCard).join(''):empty('Sem anúncios','Os anúncios que publicares aparecem aqui.')}
function home(){const n=unread(),m=unreadMessages();return`<div class="search-top">${searchBox('globalSearch','Pesquisar no Aquipay',S.searchText,'clearSearch')}<button class="btn ic add" data-a="pub" aria-label="Publicar">${ic('plus')}</button></div><header class="top"><h1 class="logo">${LOGO}</h1><div class="row"><button class="btn ic" data-a="nt" aria-label="Notificações">${ic('bell')}${n?`<span class="bdg">${n>99?'99+':n}</span>`:''}</button><button class="btn ic" data-a="messages" aria-label="Mensagens">${ic('message')}${m?`<span class="bdg">${m>99?'99+':m}</span>`:''}</button><button class="btn ic" data-a="menu" aria-label="Menu">${av(S.me,28).replace('background:var(--in)','background:transparent')}</button></div></header><nav class="tabs">${[['vagas','Vagas'],['cand','Candidaturas'],['mine','Meus anúncios']].map(([k,l])=>`<button class="tab ${S.tab===k?'on':''}" data-a="tab" data-id="${k}">${l}</button>`).join('')}</nav><main class="main" id="feed">${feed()}</main>`}
const sel=(k,l,o,v)=>`<div class="fd"><label for="${k}">${l}</label><select id="${k}" data-k="${k}">${o.map(([a,b])=>`<option value="${a}" ${String(a)===String(v)?'selected':''}>${b}</option>`).join('')}</select></div>`;
const tg=(k,l,d,on)=>`<label class="tg"><span><b>${l}</b>${d?`<small>${d}</small>`:''}</span><input type="checkbox" data-set="${k}" ${on?'checked':''}><i></i></label>`;
const kv=(a,b)=>`<div class="kv"><span>${a}</span><small>${esc(b)}</small></div>`;
const notifState=()=>isNativeApp()&&nativePushPlugin()?'Notificações nativas do Android.':!('Notification'in window)?'Este dispositivo não suporta notificações.':Notification.permission==='granted'?'Notificações ativas neste dispositivo.':Notification.permission==='denied'?'Bloqueadas nas definições do navegador.':'Ativa as notificações para receber mensagens, candidaturas e novos trabalhos.';
const legalList=()=>DOC_ORDER.map(([g,ids])=>`<h4>${g}</h4><div class="menu">${ids.map(id=>`<button class="mi" data-a="openDoc" data-id="${id}">${ic(DOCS[id].icon)}<span>${DOCS[id].title}</span></button>`).join('')}</div>`).join('');
const BACK={set:'home',legal:()=>S.legalFrom||'home',doc:()=>S.me?'legal':'home'};
const views={home,reset:()=>`<div class="auth"><h1 class="logo">${LOGO}</h1><h2 style="text-align:center">Nova palavra-passe</h2><p class="err" id="err" role="alert"></p>${fd('Nova palavra-passe','rp','password','Mínimo 10 caracteres','autocomplete="new-password"')}${fd('Repete a nova palavra-passe','rp2','password','','autocomplete="new-password"')}${fd('Código do autenticador (se ativado)','rp2fa','text','Código de 6 dígitos ou recuperação','inputmode="text"')}<button class="btn" data-a="doReset">Guardar palavra-passe</button><p class="sw"><a class="link" data-a="toLogin">Voltar a entrar</a></p></div>`,explore:()=>`${bar('Explorar perfis públicos')}<div class="pad stack">${searchBox('publicSearch','Nome, profissão ou cidade','','clearPublic')}<div id="publicResults"><p class="mut">Pesquisa profissionais sem precisares de iniciar sessão.</p></div><a class="link" data-a="toLogin">Entrar no Aquipay</a></div>`,
pub:()=>`${bar('Novo anúncio')}<div class="pad stack">${fd('Título','pt','text','Ex.: Montagem de móveis')}${sel('ptipo','Tipo',Object.entries(TIPO),'biscato')}${fd('Preço em Kz (opcional)','pp','number','8000','inputmode="numeric"')}${fd('Localização','pl','text','Ex.: Luanda, Talatona')}<div class="fd"><label for="pd">Descrição</label><textarea id="pd" placeholder="Descreve o trabalho, horário e requisitos"></textarea></div><div><button class="btn" data-a="addpic">${ic('image')} Adicionar fotos</button><div class="thumbs" id="th"></div></div><button class="btn" data-a="publish">Publicar</button></div>`,
coins:()=>`${bar('Moedas e plano')}<div class="pad"><div class="bal"><b>${S.me.coins||0}</b>moedas${hasPlus(S.me)?`<p class="ok">Plus ativo até ${fmtDate(S.me.plusUntil)}</p>`:''}</div><h4>Plano Plus</h4><div class="card"><h3>Plus · $19.99 / mês</h3><p class="mut" style="margin:.3rem 0 .8rem">Candidaturas ilimitadas, sem gastar moedas.</p><button class="btn" data-a="checkout" data-id="plus">Ativar Plus</button></div><h4>Comprar moedas</h4>${PKG.map(p=>`<div class="card row2" style="align-items:center"><div><b>${p[0]} moedas</b>${p[2]?`<small style="display:block">+${p[2]} de bónus</small>`:''}</div><button class="btn" style="width:auto" data-a="checkout" data-id="${p[0]}">$${p[1]}</button></div>`).join('')}</div>`,
me:()=>{const u=S.me;return`${bar('Perfil')}<div class="pad stack"><div class="pf">${av(u,88)}<button class="btn" style="width:auto" data-a="addavatar">${ic('image')} Alterar foto</button></div>${fd('Nome','mn','text','',`value="${esc(u.nome)}"`)}${fd('Cidade','mc','text','Ex.: Luanda',`value="${esc(u.cidade||'')}"`)}${fd('Telefone','mt','tel','',`value="${esc(u.tel||'')}"`)}<div class="fd"><label for="mb">Biografia</label><textarea id="mb">${esc(u.bio||'')}</textarea></div>${fd('Profissões (separadas por vírgula)','mprof','text','Ex.: Electricista, Técnico de informática',`value="${esc((u.professions||[]).join(', '))}"`)}${fd('Competências (separadas por vírgula)','mskills','text','Ex.: Excel, soldadura, atendimento',`value="${esc((u.skills||[]).join(', '))}"`)}<div class="fd"><label for="mexp">Experiência profissional (uma por linha)</label><textarea id="mexp" placeholder="Cargo | Empresa | Período">${esc((u.experience||[]).map(x=>[x.role||x.title||'',x.company||'',x.period||''].join(' | ')).join('\n'))}</textarea></div><div class="fd"><label for="medu">Formação (uma por linha)</label><textarea id="medu" placeholder="Curso | Instituição | Ano">${esc((u.education||[]).map(x=>[x.course||x.title||'',x.school||'',x.year||''].join(' | ')).join('\n'))}</textarea></div><div class="fd"><label for="mport">Portefólio (um projeto por linha)</label><textarea id="mport" placeholder="Projeto | Descrição">${esc((u.portfolio||[]).map(x=>[x.title||x.name||'',x.description||''].join(' | ')).join('\n'))}</textarea></div><div class="fd"><label for="mpublic">Perfil público</label><select id="mpublic"><option value="true" ${u.publicProfile!==false?'selected':''}>Qualquer pessoa pode encontrar e ver o perfil</option><option value="false" ${u.publicProfile===false?'selected':''}>Perfil privado</option></select></div><button class="btn" data-a="saveme">Guardar perfil</button><button class="btn secondary" data-a="shareProfile">Partilhar perfil</button><button class="btn secondary" data-a="copyProfile">Copiar link do perfil</button><h4>Documentos e portefólio</h4><p class="mut">Envia CV, certificados, trabalhos e vídeo. Escolhe se cada ficheiro pode aparecer no perfil público.</p>${sel('doccat','Tipo de ficheiro',[['cv','CV / Currículo'],['certificate','Certificado'],['portfolio','Portefólio'],['experience','Experiência profissional'],['education','Formação académica'],['intro_video','Vídeo de apresentação']],'cv')}<div class="fd"><label for="docpublic">Visibilidade do ficheiro</label><select id="docpublic"><option value="false" selected>Privado</option><option value="true">Visível no perfil público</option></select></div><button class="btn secondary" data-a="addDocument">Escolher ficheiro no dispositivo</button>${S.documents.map(d=>`<div class="row2 card"><span>${esc(d.original_name)}<small>${d.is_public?'Visível no perfil':'Privado'}</small></span><button class="btn secondary" style="width:auto" data-a="deleteDocument" data-id="${d.id}">Apagar</button></div>`).join('')}<h4>Verificação</h4><p class="mut">${u.verified?'A tua conta está verificada.':u.verif==='pendente'?'Pedido de verificação enviado.':'Contas verificadas transmitem mais confiança a quem se candidata.'}</p>${u.verified||u.verif==='pendente'?'':'<button class="btn" data-a="verif">Pedir verificação</button>'}</div>`},
set:()=>{const u=S.me,n=S.st.notif||{};return`${bar('Definições')}<div class="pad stack"><h4>Conta</h4><div class="group">${kv('Nome',u.nome)}${kv('Email',u.email||'—')}</div><div class="menu"><button class="mi" data-a="open" data-id="me">${ic('user')}<span>Editar perfil e documentos</span></button><button class="mi" data-a="open" data-id="coins">${ic('coins')}<span>Moedas e plano</span></button></div><h4>Aparência</h4>${sel('lang','Idioma',LANGS.map(([c,,n])=>[c,n]),LANG)}${sel('theme','Tema',[['auto','Automático'],['light','Claro'],['dark','Escuro']],S.st.theme)}${sel('font','Tipo de letra',[['padrao','Padrão'],['redonda','Arredondada'],['classica','Clássica']],S.st.font)}${sel('size','Tamanho da letra',[[90,'Pequeno'],[100,'Normal'],[115,'Grande'],[130,'Muito grande']],S.st.size)}${sel('motion','Animações',[['auto','Normais'],['reduzida','Reduzidas']],S.st.motion)}<h4>Notificações</h4><p class="mut">${notifState()}</p>${(isNativeApp()&&nativePushPlugin())||('Notification'in window&&Notification.permission==='default')?'<button class="btn" data-a="push">Ativar notificações</button>':''}<div class="group">${tg('notif.candidaturas','Candidaturas','Quando alguém se candidata ou responde a uma candidatura',n.candidaturas!==false)}${tg('notif.pagamentos','Pagamentos','Confirmações de pagamento dos trabalhos',n.pagamentos!==false)}${tg('notif.novidades','Novos trabalhos e publicações','Quando alguém publicar um novo trabalho, produto ou serviço',!!n.novidades)}</div><h4>Privacidade</h4><div class="group">${tg('publicProfile','Perfil público','Qualquer pessoa pode encontrar e ver o teu perfil',u.publicProfile!==false)}</div><h4>Dados e armazenamento</h4>${sel('saver','Qualidade das fotografias',[['off','Alta'],['on','Poupar dados']],S.st.saver)}<div class="menu"><button class="mi" data-a="exportData">${ic('archive')}<span>Exportar os meus dados</span></button><button class="mi" data-a="askClear">${ic('trash')}<span>Limpar dados deste dispositivo</span></button></div><h4>Segurança e privacidade</h4><div class="menu"><button class="mi" data-a="openSecurity">${ic('shield')}<span>Segurança da conta, 2FA e dispositivos</span></button>${u.google?'':`<button class="mi" data-a="askPassword">${ic('lock')}<span>Alterar palavra-passe</span></button>`}<button class="mi" data-a="blockedList">${ic('shield')}<span>Utilizadores bloqueados</span></button><button class="mi" data-a="logout">${ic('logout')}<span>Terminar sessão</span></button><button class="mi bad" data-a="askDelete">${ic('trash')}<span>Eliminar a minha conta</span></button></div><h4>Legal e ajuda</h4><div class="menu"><button class="mi" data-a="open" data-id="legal">${ic('file')}<span>Termos, privacidade e ajuda</span></button></div><p class="legal-note" style="margin-top:1rem">Aquipay ${APP_VERSION}</p></div>`},
security:()=>{
 const q=S.securityStatus||{twoFactorEnabled:false,sessions:[]};
 const bioButton=!isNativeApp()?'<p class="mut">Disponível apenas na aplicação Android instalada.</p>':(S.biometricEnabled?'<button class="btn danger" data-a="toggleBiometric">Desativar bloqueio biométrico</button>':'<button class="btn" data-a="toggleBiometric"'+((S.biometricInfo?.isAvailable||S.biometricInfo?.deviceIsSecure)?'':' disabled')+'>Ativar bloqueio biométrico</button>');
 const sessionRows=(q.sessions||[]).map(x=>'<div class="row2"><span><b>'+(x.current?'Este dispositivo':'Sessão ativa')+'</b><small>'+esc(new Date(x.createdAt).toLocaleString('pt-AO'))+'</small></span>'+(x.current?'<span class="pill">Atual</span>':'<button class="btn secondary" style="width:auto" data-a="revokeSession" data-id="'+esc(x.id)+'">Terminar</button>')+'</div>').join('');
 return `${bar('Segurança da conta')}<div class="pad stack"><div class="card"><b>Verificação em dois passos</b><p class="mut">Usa o Google Authenticator ou outra aplicação compatível com códigos TOTP para confirmar os acessos.</p><p class="${q.twoFactorEnabled?'ok':'mut'}">${q.twoFactorEnabled?'Ativa':'Desativada'}</p>${q.twoFactorEnabled?'<button class="btn secondary" data-a="regenerateRecovery">Gerar novos códigos de recuperação</button><button class="btn danger" data-a="disableTotp">Desativar verificação em dois passos</button>':'<button class="btn" data-a="setupTotp">Configurar Google Authenticator</button>'}</div><div class="card"><b>Bloqueio biométrico</b><p class="mut">Protege a abertura do AquiPay com impressão digital, reconhecimento facial compatível ou PIN do dispositivo. O token da sessão fica guardado no armazenamento seguro do Android.</p><p class="${S.biometricEnabled?'ok':'mut'}">${S.biometricEnabled?'Ativo neste dispositivo':(S.biometricInfo?.isAvailable||S.biometricInfo?.deviceIsSecure?'Disponível para ativar':'Não disponível neste dispositivo')}</p>${bioButton}</div><div class="card"><b>Dispositivos e sessões</b><p class="mut">Sessões ativas: ${q.sessions?.length||0}. Se não reconheceres um acesso, termina essa sessão.</p><button class="btn secondary" data-a="revokeOthers">Terminar todas as outras sessões</button>${sessionRows}</div><p class="mut">As sessões expiram após 7 dias. Protege também o email associado à tua conta e nunca partilhes códigos de verificação.</p><button class="btn secondary" data-a="refreshSecurity">Atualizar estado</button></div>`
},
legal:()=>`${bar('Legal e ajuda')}<div class="pad">${legalList()}</div>`,
doc:()=>`${bar('')}<div class="pad">${docHtml(S.doc)}</div>`,
notfound:()=>`<main class="notfound"><div class="nf-mark">${LOGO}</div><div class="nf-code">404</div><h1>Esta página não existe</h1><p>O endereço que tentaste abrir pode estar incorreto ou a página foi removida.</p><button class="btn" data-a="toLogin">Voltar ao início</button><a class="nf-link" href="/">Ir para a página inicial</a></main>`,
nt:()=>{const l=S.notifs.filter(n=>n.uid===S.me.id).sort((a,b)=>b.at-a.at);return`${bar('Notificações')}<div class="pad">${l.length?l.map(n=>`<div class="card"><p>${esc(n.txt)}</p><small>${ago(n.at)}</small></div>`).join(''):empty('Sem notificações','Os avisos de candidaturas e pagamentos aparecem aqui.')}</div>`},messages:()=>{const ids=[...new Set(S.messages.filter(x=>x.from===S.me.id||x.to===S.me.id).map(x=>x.from===S.me.id?x.to:x.from))];return`${bar('Mensagens')}<div class="pad">${ids.length?ids.map(id=>{const u=U(id)||{nome:'Utilizador'},last=S.messages.filter(x=>(x.from===S.me.id&&x.to===id)||(x.from===id&&x.to===S.me.id)).sort((a,b)=>b.at-a.at)[0];return`<div class="card ho">${av(u,42)}<div><b>${esc(u.nome)}</b><small>${esc(last?.text||'Conversa')}</small></div></div>`}).join(''):empty('Ainda não tens mensagens','As conversas sobre propostas e anúncios aparecerão aqui.')}</div>`}};
function deletionView(){const due=S.me?.deletionDueAt?new Date(S.me.deletionDueAt).toLocaleDateString('pt-AO'):'dentro de 30 dias';return `<div class="auth"><h1 class="logo">${LOGO}</h1><h2>Pedido de eliminação ativo</h2><p class="mut" style="margin:1rem 0">A tua conta está desativada e deixará de aparecer no Aquipay. Os dados serão eliminados permanentemente em ${esc(due)}. Podes cancelar o pedido antes dessa data.</p><div class="stack"><button class="btn" data-a="cancelDeletion">Cancelar pedido de eliminação</button><button class="btn secondary" data-a="logout">Terminar sessão</button></div></div>`}
function biometricLockView(){return `<div class="auth"><h1 class="logo">${LOGO}</h1><h2 style="text-align:center">AquiPay bloqueado</h2><p class="mut">Confirma a tua identidade para voltar a aceder à tua conta.</p><button class="btn" data-a="unlockApp">Desbloquear com biometria</button></div>`}
function twoFactorLoginView(){return `<div class="auth"><h1 class="logo">${LOGO}</h1><h2 style="text-align:center">Verificação em dois passos</h2><p class="mut">Introduz o código de 6 dígitos do Google Authenticator. Também podes usar um código de recuperação.</p><p class="err" id="login2faErr" role="alert"></p><input id="login2fa" inputmode="numeric" autocomplete="one-time-code" placeholder="Código de segurança" maxlength="20"><button class="btn" data-a="verifyLogin2fa">Confirmar acesso</button><button class="btn secondary" data-a="cancelLogin2fa">Voltar ao início</button></div>`}
async function completeCloudLogin(cloud,isGoogle=false){const email=String(cloud.user.email||'').toLowerCase();let u=S.users.find(x=>x.cloudId===cloud.user.id)||S.users.find(x=>x.email===email),isNew=false;if(!u){isNew=true;u={id:nid(),nome:cloud.user.name||email.split('@')[0],email,publicProfile:true,coins:10,plusUntil:null,daily:{date:day(),count:0},at:Date.now()};S.users.push(u)}u.apiToken=cloud.token;u.cloudId=cloud.user.id;u.nome=cloud.user.name;u.email=email;if(isGoogle)u.google=true;delete u.pw;u.deletionRequestedAt=cloud.user.deletionRequestedAt||null;u.deletionDueAt=cloud.user.deletionDueAt||null;await saveUser(u);if(!S.users.some(x=>x.id===u.id))S.users.push(u);S.authGoogle=false;await enter(u);if(isNew)notify(u.id,'Bem-vindo ao Aquipay. Recebeste 10 moedas de boas-vindas.','novidades')}
function render(){const a=$('app');if(!S.ready){a.innerHTML=skel();return}const L=langbar();if(S.biometricLocked){a.innerHTML=L+biometricLockView();return}if(S.shared){a.innerHTML=L+sharedView(S.shared);return}if(S.me?.deletionRequestedAt){a.innerHTML=L+deletionView();return}if(!S.me||S.v==='reset'){if(S.authChallenge){a.innerHTML=L+twoFactorLoginView();return}const pub=['explore','doc','reset','notfound'].includes(S.v);a.innerHTML=L+(pub?views[S.v]():auth(S.v==='reg'));if(!pub)initGoogle();return}a.innerHTML=L+(views[S.v]||home)();if(S.v==='pub')thumbs()}
const go=v=>{S.v=v;render()};
function thumbs(){const t=$('th');if(t)t.innerHTML=S.pics.map((b,i)=>`<div><img src="${src(b)}" alt="Pré-visualização"><button class="btn ic" data-a="rmpic" data-id="${i}" aria-label="Remover">${ic('x')}</button></div>`).join('')}
function pick(multi,cb){const i=document.createElement('input');i.type='file';i.accept='image/*';i.multiple=multi;i.onchange=async()=>{try{cb(await Promise.all([...i.files].map(f=>shrink(f))))}catch{toast('Não foi possível ler a imagem')}};i.click()}
const cost=u=>hasPlus(u)?0:((u.daily&&u.daily.date===day()?u.daily.count:0)>=1?5:0);

/* links públicos de partilha: snapshot textual autónomo */
const SHARE_ORIGIN='https://aquipay.isabstudio.dev';
function makeShareUrl(data){const enc=x=>{const bytes=new TextEncoder().encode(JSON.stringify(x));let bin='';bytes.forEach(b=>bin+=String.fromCharCode(b));return btoa(bin).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')};const d={...data};let u=SHARE_ORIGIN+'/?share='+enc(d);for(const k of ['description','bio']){while(u.length>1800&&d[k]&&d[k].length>40){d[k]=d[k].slice(0,Math.floor(d[k].length*.7)).trimEnd()+'…';u=SHARE_ORIGIN+'/?share='+enc(d)}}return u}
function decodeShare(token){try{const b=token.replace(/-/g,'+').replace(/_/g,'/'),bin=atob(b),u=Uint8Array.from(bin,c=>c.charCodeAt(0));return JSON.parse(new TextDecoder().decode(u))}catch{return null}}
const shortDate=j=>typeof j==='number'?fmtMonth(j):String(j||'');
function sharedView(d){if(!d||!['post','profile'].includes(d.type))return`<div class="auth"><h2>Link inválido</h2><p class="mut">Este conteúdo não está disponível.</p><a class="btn" href="/">Abrir Aquipay</a></div>`;if(d.type==='post'){const kind=TIPO[d.kind]||d.kind||'',price=typeof d.price==='number'?kz(d.price):T(d.price||'A combinar');return`<header class="top"><h1 class="logo">${LOGO}</h1><span class="pill">Publicação partilhada</span></header><main class="main"><article class="card"><div class="ho"><div class="av">${esc((d.author||'A').slice(0,2).toUpperCase())}</div><div><b>${esc(d.author||'Utilizador')}</b><small>${esc(d.city||'')}</small></div></div><h2>${esc(d.title||'Publicação')}</h2><p class="mut">${esc(d.location||T('Local a combinar'))} · ${esc(T(kind))}</p><p class="pr">${esc(price)}</p><p>${esc(d.description||'')}</p></article><a class="btn" href="/">Abrir Aquipay</a></main>`}const list=(a,t)=>a&&a.length?`<h4>${t}</h4><p>${a.map(esc).join(' · ')}</p>`:'';return`<header class="top"><h1 class="logo">${LOGO}</h1><span class="pill">Perfil partilhado</span></header><main class="main"><section class="card"><div class="pf"><div class="av" style="width:5rem;height:5rem">${esc((d.name||'A').slice(0,2).toUpperCase())}</div><h2>${esc(d.name||'Utilizador')}</h2><p class="mut">${esc(d.city||'')}</p></div>${d.bio?`<p>${esc(d.bio)}</p>`:''}${list(d.professions,'Profissões')}${list(d.skills,'Competências')}<p class="mut">No Aquipay desde ${esc(shortDate(d.joined))}</p></section><a class="btn" href="/">Abrir Aquipay</a></main>`}
function linkSheet(url){sheet(`<h3 style="margin-bottom:.8rem">Copiar link</h3><input class="linkbox" id="lk" value="${esc(url)}" readonly aria-label="Link"><button class="btn" style="margin-top:.8rem" data-a="close">Concluir</button>`);setTimeout(()=>{const i=$('lk');i&&(i.focus(),i.select())},50)}
async function shareLink(url,title){if(navigator.share){try{await navigator.share({title:T(title),text:T('Vê no Aquipay'),url});return}catch(e){if(e.name==='AbortError')return}}try{await navigator.clipboard.writeText(url);toast('Link copiado')}catch{linkSheet(url)}}
function postShareData(v){const o=U(v.ownerId)||{};return{v:2,type:'post',title:String(v.titulo||'').slice(0,120),description:String(v.desc||'').slice(0,500),author:o.nome||'',city:o.cidade||'',location:String(v.local||'').slice(0,80),kind:v.tipo,price:v.preco||null,at:v.at}}
function profileShareData(u=S.me){return{v:2,type:'profile',name:u.nome,city:u.cidade||'',bio:String(u.bio||'').slice(0,300),professions:(u.professions||[]).slice(0,8),skills:(u.skills||[]).slice(0,12),joined:u.at}}
const profilePublic=u=>u.publicProfile!==false;

