async doReset(){const a=$('rp').value,b=$('rp2').value,r=$('err');if(a.length<10)return r.textContent=T('A palavra-passe deve ter pelo menos 10 caracteres.');if(a!==b)return r.textContent=T('As palavras-passe não coincidem.');try{await api('/api/auth/reset',{method:'POST',body:JSON.stringify({token:S.resetToken,password:a,code:$('rp2fa')?.value.trim()||''})});S.resetToken=null;S.v='home';render();toast('Palavra-passe alterada. Já podes entrar.')}catch(x){r.innerHTML=esc(x.message)+' <a class="link" data-a="forgotFromReset">Pedir novo link</a>'}},
